121	export function claudeUsageEvent(
122	  rowValue: unknown,
123	  session: string,
124	): ObserveBatchEvent | null {
125	  const row = object(rowValue),
126	    message = object(row?.message),
127	    usage = object(message?.usage);
128	  if (
129	    !id(session) ||
130	    row?.type !== "assistant" ||
131	    row.sessionId !== session ||
132	    !id(message?.id) ||
133	    !usage
134	  )
135	    return null;
136	  const result = event(
137	    "claude-code",
138	    "claude.assistant_usage.v1",
139	    session,
140	    message.id,
141	    row.timestamp,
142	  );
143	  const attrs = result.attrs!;
144	  if (id(message.model)) attrs.model = message.model;
145	  counter(attrs, "uncached_input_tokens", usage.input_tokens);
146	  counter(attrs, "cache_read_input_tokens", usage.cache_read_input_tokens);
147	  counter(attrs, "cache_write_input_tokens", usage.cache_creation_input_tokens);
148	  summedInput(attrs);
149	  // Assistant output_tokens can be a message_start placeholder. Do not report it.
150	  return result;
151	}
152	
153	export function codexUsageEvent(
154	  rowValue: unknown,
155	  session: string,
156	): ObserveBatchEvent | null {
157	  const row = object(rowValue),
158	    payload = object(row?.payload),
159	    usage = object(payload?.usage);
160	  if (
161	    !id(session) ||
162	    row?.type !== "token_usage_record" ||
163	    payload?.thread_id !== session ||
164	    !id(payload.response_id) ||
165	    !usage
166	  )
167	    return null;
168	  const result = event(
169	    "codex",
170	    "codex.token_usage_record.v1",
171	    session,
172	    payload.response_id,
173	    row.timestamp,
174	  );
175	  const attrs = result.attrs!;
176	  for (const key of [
177	    "input_tokens",
178	    "output_tokens",
179	    "reasoning_output_tokens",
180	    "total_tokens",
181	  ])
182	    counter(attrs, key, usage[key]);
183	  counter(attrs, "cache_read_input_tokens", usage.cached_input_tokens);
184	  counter(attrs, "cache_write_input_tokens", usage.cache_write_input_tokens);
185	  if (
186	    [
187	      "input_tokens",
188	      "cache_read_input_tokens",
189	      "cache_write_input_tokens",
190	    ].every((key) => attrs[key] !== undefined)
191	  ) {
192	    const uncached =
193	      Number(attrs.input_tokens) -
194	      Number(attrs.cache_read_input_tokens) -
195	      Number(attrs.cache_write_input_tokens);
196	    if (count(uncached)) attrs.uncached_input_tokens = String(uncached);
197	    else attrs.usage_invalid = "1";
198	  }
199	  // thread_token_usage is cumulative and must never be added to these counters.
200	  return result;
201	}
