203	export function openCodeUsageEvent(
204	  partValue: unknown,
205	): ObserveBatchEvent | null {
206	  const part = object(partValue),
207	    tokens = object(part?.tokens),
208	    cache = object(tokens?.cache);
209	  if (
210	    part?.type !== "step-finish" ||
211	    !id(part.sessionID) ||
212	    !id(part.id) ||
213	    !id(part.messageID) ||
214	    !tokens
215	  )
216	    return null;
217	  const result = event(
218	    "opencode",
219	    "opencode.step_finish.v1",
220	    part.sessionID,
221	    part.id,
222	  );
223	  const attrs = result.attrs!;
224	  counter(attrs, "uncached_input_tokens", tokens.input);
225	  counter(attrs, "cache_read_input_tokens", cache?.read);
226	  counter(attrs, "cache_write_input_tokens", cache?.write);
227	  counter(attrs, "reported_output_tokens", tokens.output);
228	  counter(attrs, "reasoning_output_tokens", tokens.reasoning);
229	  summedInput(attrs);
230	  // Output/reasoning overlap changed across OpenCode versions. Keep raw output separate.
231	  return result;
232	}
